<script setup>
import {computed,onMounted,onBeforeUnmount,ref,watch} from 'vue'
import Chart from './Chart.vue'
import LakeCurvePanel from './LakeCurvePanel.vue'
import WarningPanel from './WarningPanel.vue'
import {api,number} from './api.mjs'
const props=defineProps({boot:Object,busy:Boolean})
const emit=defineEmits(['refresh','navigate','forecast'])
const tab=ref('weather'),method=ref('manual'),sources=ref([]),inputs=ref([]),forecasts=ref([]),curves=ref([]),sourceId=ref(''),inputId=ref(''),curveId=ref(''),issueDate=ref(''),days=ref(10),daily=ref([]),scenarioName=ref('未来天气情景'),bulkRain=ref(0),bulkTemp=ref(5),file=ref(null),working=ref(false),error=ref(''),message=ref(''),check=ref(null),pending=ref([]),detail=ref(null),selectedForecast=ref(''),latestMain=ref(false),thresholdRows=ref([]),openRow=ref(-1),evaporationPreview=ref(null),evaporationLoading=ref(false),evaporationError=ref('')
const areas=[['zajia','扎加藏布'],['zagen','扎根藏布'],['boqu','波曲'],['ali','阿里藏布'],['duja','杜加'],['fringe','湖周直接来水'],['lake','湖面']]
let timer,disposed=false,polling=false,evaporationRequest=0
const selectedSource=computed(()=>sources.value.find(v=>v.id===sourceId.value)),selectedInput=computed(()=>inputs.value.find(v=>v.id===inputId.value)),availableInputs=computed(()=>inputs.value.filter(v=>!v.sourceResultId||v.sourceResultId===sourceId.value))
const dateAt=(base,index)=>{if(!base)return '';return new Date(Date.parse(base+'T00:00:00Z')+index*86400000).toISOString().slice(0,10)}
function rows(){daily.value=Array.from({length:Number(days.value)},(_,i)=>({date:dateAt(issueDate.value,i),precipitationMm:'',temperatureC:'',evaporationMm:'',rainStartHour:0,rainEndHour:24,rainShape:'uniform',areas:Object.fromEntries(areas.map(([id])=>[id,{precipitationMm:'',temperatureC:'',evaporationMm:''}])),...(daily.value[i]||{}),date:dateAt(issueDate.value,i)}))}
watch([days,issueDate],rows)
watch([sourceId,issueDate,days],async()=>{const ticket=++evaporationRequest;evaporationPreview.value=null;evaporationError.value='';if(!sourceId.value||!issueDate.value||Number(days.value)<7||Number(days.value)>10)return;evaporationLoading.value=true;try{const preview=await api('forecast-inputs/evaporation-preview',{sourceResultId:sourceId.value,issueTime:issueDate.value+'T00:00:00',days:Number(days.value),evaporation:{method:'seasonal-hourly'}});if(ticket===evaporationRequest&&!disposed)evaporationPreview.value=preview}catch(e){if(ticket===evaporationRequest&&!disposed)evaporationError.value=e.message}finally{if(ticket===evaporationRequest&&!disposed)evaporationLoading.value=false}})
watch([sourceId,inputId,curveId,latestMain],()=>check.value=null)
watch(sourceId,()=>{const source=selectedSource.value;if(source?.stateTime)issueDate.value=source.stateTime.slice(0,10);if(!availableInputs.value.some(v=>v.id===inputId.value))inputId.value=availableInputs.value[0]?.id||''})
function request(){return {sourceResultId:sourceId.value,inputId:inputId.value,curveId:curveId.value||null,useLatestMainStation:latestMain.value,thresholds:thresholdRows.value.filter(v=>v.level!=='').map(v=>({name:v.name||'关注水位',level:Number(v.level)}))}}
function payloadDaily(){return daily.value.map(row=>{const overrides={};let lake;for(const [id] of areas){const value=Object.fromEntries(Object.entries(row.areas[id]).filter(([,v])=>v!==''&&v!=null).map(([key,value])=>[key,Number(value)]));if(Object.keys(value).length){if(id==='lake')lake=value;else overrides[id]=value}}return {date:row.date,precipitationMm:Number(row.precipitationMm),temperatureC:Number(row.temperatureC),rainStartHour:Number(row.rainStartHour),rainEndHour:Number(row.rainEndHour),rainShape:row.rainShape,overrides,...(row.evaporationMm!==''&&row.evaporationMm!=null?{evaporationMm:Number(row.evaporationMm)}:{}),...(lake?{lake}:{})}})}
async function run(fn){working.value=true;error.value='';message.value='';try{return await fn()}catch(e){error.value=e.message}finally{working.value=false}}
async function load(){const results=await Promise.allSettled([api('forecasts/sources'),api('forecast-inputs'),api('forecasts'),api('lake-curves')]);if(disposed)return;const [s,i,f,c]=results;if(s.status==='fulfilled')sources.value=s.value.items||[];else if(!sources.value.length)sources.value=(props.boot?.publishedResults||[]).map(v=>({...v,stateTime:v.stateTime||v.end}));if(i.status==='fulfilled')inputs.value=i.value.items||[];if(f.status==='fulfilled')forecasts.value=f.value.items||[];if(c.status==='fulfilled'){curves.value=c.value.items||[];if(!curveId.value)curveId.value=c.value.defaultCurveId||curves.value[0]?.id||''}if(!sourceId.value)sourceId.value=sources.value.find(v=>v.id===props.boot?.homeResultId)?.id||sources.value[0]?.id||'';if(!issueDate.value){issueDate.value=selectedSource.value?.stateTime?.slice(0,10)||new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Shanghai'});rows()}if(!inputId.value)inputId.value=availableInputs.value[0]?.id||'';if(s.status==='rejected'&&!sources.value.length)throw s.reason}
function bulk(){for(const row of daily.value){row.precipitationMm=bulkRain.value;row.temperatureC=bulkTemp.value}}
async function manual(){await run(async()=>{if(daily.value.some(row=>row.precipitationMm===''||row.temperatureC===''))throw Error('请填齐每一天的降水和气温。');const result=await api('forecast-inputs/manual',{name:scenarioName.value,sourceResultId:sourceId.value,issueTime:issueDate.value+'T00:00:00',days:Number(days.value),daily:payloadDaily(),evaporation:{method:'seasonal-hourly'}});await load();inputId.value=result.id;message.value='已保存逐时天气情景，可继续检查起报条件。';tab.value='run';emit('refresh')})}
async function hourly(){await run(async()=>{if(!file.value)throw Error('请选择逐时Excel文件');const response=await fetch('/api/model/upload?'+new URLSearchParams({filename:file.value.name,format:'exchange'}),{method:'PUT',body:file.value});const upload=await response.json();if(!response.ok)throw Error(upload.error||'上传失败');const result=await api('forecast-inputs/hourly',{name:scenarioName.value,sourceResultId:sourceId.value,issueTime:issueDate.value+'T00:00:00',days:Number(days.value),filename:upload.filename,path:'incoming/'+upload.filename});await load();inputId.value=result.id;message.value='逐时气象已导入。';tab.value='run';emit('refresh')})}
async function ensemble(){await run(async()=>{const task=await api('forecast-inputs/ensemble',{sourceResultId:sourceId.value,days:15});pending.value.push({...task,purpose:'weather'});message.value='已提交集合气象获取任务。';emit('refresh')})}
async function preflight(){await run(async()=>{check.value=await api('forecasts/preflight',request());if(check.value.ready)message.value='起报检查通过，可以运行预测。'})}
async function predict(){await run(async()=>{const ready=await api('forecasts/preflight',request());check.value=ready;if(!ready.ready)return;const task=await api('forecasts',{...request(),name:scenarioName.value||'色林错水文预测'});pending.value.push({...task,purpose:'forecast'});message.value='已提交预测计算。';emit('refresh')})}
async function openForecast(id){await run(async()=>{detail.value=await api('forecasts/'+encodeURIComponent(id));selectedForecast.value=id;tab.value='results';emit('forecast',detail.value)})}
async function poll(){if(polling||!pending.value.length||disposed)return;polling=true;try{for(const old of [...pending.value]){const task=await api('tasks/'+encodeURIComponent(old.id));if(disposed)return;const index=pending.value.findIndex(v=>v.id===old.id);if(index<0)continue;if(task.status==='succeeded'){pending.value.splice(index,1);await load();if(old.purpose==='weather'){inputId.value=task.result?.id||task.result?.inputId||'';tab.value='run';message.value='集合气象已保存，请检查起报条件。'}else{const id=task.result?.id;if(id)await openForecast(id)}emit('refresh')}else if(['failed','cancelled','interrupted'].includes(task.status)){pending.value.splice(index,1);error.value=task.message||'任务未完成'}else pending.value[index]={...task,purpose:old.purpose}}}catch(e){if(!disposed)error.value=e.message}finally{polling=false}}
const resultRows=computed(()=>(detail.value?.times||[]).map((time,i)=>({time,level:detail.value.control.lakeLevel[i],level10:detail.value.quantiles?.p10?.lakeLevel?.[i],level50:detail.value.quantiles?.p50?.lakeLevel?.[i],level90:detail.value.quantiles?.p90?.lakeLevel?.[i],inflow:detail.value.control.inflow[i],inflow10:detail.value.quantiles?.p10?.inflow?.[i],inflow50:detail.value.quantiles?.p50?.inflow?.[i],inflow90:detail.value.quantiles?.p90?.inflow?.[i],rain:detail.value.control.lakeRainMm[i],evaporation:detail.value.control.lakeEvaporationMm[i]})))
const ensembleResult=computed(()=>Number(detail.value?.memberCount)>1)
const levelSeries=computed(()=>ensembleResult.value?[{key:'level10',label:'P10',options:{lineStyle:{type:'dashed',width:1}}},{key:'level50',label:'P50'},{key:'level90',label:'P90',options:{lineStyle:{type:'dashed',width:1}}},{key:'level',label:'控制成员',options:{lineStyle:{width:1}}}]:[{key:'level',label:'预测湖位'}])
const flowSeries=computed(()=>ensembleResult.value?[{key:'inflow10',label:'P10'},{key:'inflow50',label:'P50'},{key:'inflow90',label:'P90'},{key:'inflow',label:'控制成员'}]:[{key:'inflow',label:'预测入湖流量'}])
const dailyResults=computed(()=>{const values=new Map();for(const row of resultRows.value){const date=new Date(Date.parse(row.time+'Z')-3600000).toISOString().slice(0,10);if(!values.has(date))values.set(date,{date,count:0,rain:0,evaporation:0,flow:0,level:null});const value=values.get(date);value.count++;value.rain+=row.rain;value.evaporation+=row.evaporation;value.flow+=row.inflow;value.level=row.level}return [...values.values()].map(row=>({...row,flow:row.flow/row.count}))})
async function curveSaved(value){await load();curveId.value=value.id}
onMounted(()=>{load().catch(e=>error.value=e.message);rows();timer=setInterval(poll,2500)})
onBeforeUnmount(()=>{disposed=true;clearInterval(timer)})
</script>
<template>
 <div class="forecast-workspace"><nav class="workspace-tabs"><button v-for="[id,label] in [['weather','未来气象'],['run','起报与计算'],['results','预测成果'],['curve','湖泊库容关系'],['warnings','预警与报告']]" :key="id" :class="{active:tab===id}" @click="tab=id">{{label}}</button></nav>
 <p v-if="error" class="message error" role="alert">{{error}}</p><p v-if="message" class="note" role="status">{{message}}</p><div v-for="task in pending" :key="task.id" class="panel forecast-task"><b>{{task.purpose==='weather'?'获取集合气象':'运行水文预测'}}</b><span>{{task.message||'等待执行'}} · {{number(task.progress,1)}}%</span><progress :value="task.progress||0" max="100"/></div>
 <template v-if="tab==='weather'||tab==='run'"><section class="panel"><div class="panel-title"><h3>起报资料</h3><button :disabled="working" @click="run(load)">刷新可用资料</button></div><div class="forecast-grid"><label>连续状态来源<select v-model="sourceId"><option value="">请选择连续成果</option><option v-for="source in sources" :key="source.id" :value="source.id">{{source.name||source.id}}{{source.stateTime?' · '+source.stateTime.replace('T',' '):''}}</option></select></label><label>湖泊库容关系<select v-model="curveId"><option v-for="curve in curves" :key="curve.id" :value="curve.id">{{curve.name}}{{curve.provisional?' · 演示':''}}</option></select></label></div><p v-if="selectedSource" class="muted">末状态 {{selectedSource.stateTime?.replace('T',' ')||'将在起报检查时核对'}} · 原成果、参数和状态保留。</p></section></template>
 <section v-if="tab==='weather'" class="panel"><div class="panel-title"><h3>准备未来气象</h3></div><nav class="workspace-tabs"><button v-for="[id,label] in [['manual','逐日情景'],['hourly','逐时表格'],['ensemble','集合气象']]" :key="id" :class="{active:method===id}" @click="method=id">{{label}}</button></nav>
  <fieldset :disabled="working||busy"><template v-if="method!=='ensemble'"><div class="forecast-grid"><label>情景名称<input v-model="scenarioName"></label><label>起报日期 · 北京时间00时<input v-model="issueDate" type="date"></label><label>预见天数<select v-model.number="days"><option v-for="value in [7,8,9,10]" :key="value" :value="value">{{value}}天</option></select></label></div></template>
  <template v-if="method==='manual'"><div class="forecast-bulk"><label>各日降水 / mm<input v-model.number="bulkRain" type="number" min="0" step="any"></label><label>各日平均气温 / ℃<input v-model.number="bulkTemp" type="number" step="any"></label><button @click="bulk">填入各日</button></div><p class="muted">填写流域日雨量和日均温。分区留空时沿用当日全流域值，气温按计算单元高程处理。</p><p v-if="evaporationLoading" class="muted" role="status">正在读取所选成果的蒸发参考…</p><p v-else-if="evaporationError" class="note warning" role="alert">蒸发参考暂不可用：{{evaporationError}}</p><div class="table-wrap daily-input"><table><thead><tr><th>日期</th><th>降水 mm</th><th>气温 ℃</th><th>蒸发能力 mm</th><th>降雨开始</th><th>降雨结束</th><th>小时分配</th><th>分区设置</th></tr></thead><tbody><template v-for="(row,index) in daily" :key="index"><tr><td>{{row.date}}</td><td><input v-model="row.precipitationMm" type="number" min="0" step="any" :aria-label="row.date+'降水'"></td><td><input v-model="row.temperatureC" type="number" step="any" :aria-label="row.date+'气温'"></td><td><input v-model="row.evaporationMm" type="number" min="0" step="any" :aria-label="row.date+'日蒸发能力覆盖'"><small class="evap-reference">季节参考 {{evaporationPreview?number(evaporationPreview.daily[index]?.evaporationMm,2)+' mm':'—'}}</small></td><td><input v-model.number="row.rainStartHour" type="number" min="0" max="23" step="any" :aria-label="row.date+'降雨开始小时'"></td><td><input v-model.number="row.rainEndHour" type="number" min="1" max="24" step="any" :aria-label="row.date+'降雨结束小时'"></td><td><select v-model="row.rainShape" :aria-label="row.date+'降雨分配'"><option value="uniform">均匀</option><option value="triangle">三角形</option></select></td><td><button @click="openRow=openRow===index?-1:index">{{openRow===index?'收起':'分区 / 湖面'}}</button></td></tr><tr v-if="openRow===index"><td colspan="8"><div class="forecast-overrides"><div v-for="[id,label] in areas" :key="id"><b>{{label}} <small class="evap-reference">季节参考 {{evaporationPreview?(id==='lake'?number(evaporationPreview.daily[index]?.lakeEvaporationMm,2):number(evaporationPreview.daily[index]?.regions?.[id],2))+' mm':'—'}}</small></b><label>降水 / mm<input v-model="row.areas[id].precipitationMm" type="number" min="0" step="any" placeholder="沿用全流域"></label><label>气温 / ℃<input v-model="row.areas[id].temperatureC" type="number" step="any" placeholder="沿用全流域"></label><label>蒸发能力 / mm<input v-model="row.areas[id].evaporationMm" type="number" min="0" step="any" placeholder="继承全流域或季节参考"></label></div></div></td></tr></template></tbody></table></div><p class="note">蒸发能力留空时采用所选成果起报前原始ERA资料的同月、同时次参考；可输入日总量覆盖。湖面蒸发系数在水量平衡时计入。</p><button class="primary" :disabled="!sourceId||!issueDate" @click="manual">保存逐日情景</button></template>
  <template v-if="method==='hourly'"><p>上传含“时间、区域、降水(mm)、气温(℃)”列的Excel。可另填“蒸发(mm)、参考高程(m)”列。</p><p class="muted">时间标记小时区间结束，例如起报00时后的第一条为01时。区域使用 uniform、zajia、zagen、boqu、ali、duja、fringe、lake。先填uniform，再用分区行覆盖；缺少蒸发列时采用季节逐时参考。</p><label class="forecast-file">逐时Excel<input type="file" accept=".xlsx" @change="file=$event.target.files?.[0]||null"></label><div class="actions"><button class="primary" :disabled="!file||!sourceId||!issueDate" @click="hourly">检查并导入逐时情景</button></div></template>
  <template v-if="method==='ensemble'"><div class="forecast-source-card"><b>ECMWF IFS 0.25°集合</b><span>51个成员 · 最长15天 · 逐小时输入</span><p>通过Open-Meteo获取流域所需格点的降水和气温，保留实际覆盖、成员及获取时间。</p><p class="muted">原始预报时间间隔为3—6小时，小时值由供数接口处理；蒸发能力沿用起报前ERA季节逐时参考。</p><button class="primary" :disabled="!sourceId||pending.some(t=>t.purpose==='weather')" @click="ensemble">获取集合气象</button></div></template></fieldset>
 </section>
 <section v-if="tab==='run'" class="panel"><div class="panel-title"><h3>起报与计算</h3></div><fieldset :disabled="working||busy"><div class="forecast-grid"><label>未来气象输入<select v-model="inputId"><option value="">请选择已保存气象</option><option v-for="input in availableInputs" :key="input.id" :value="input.id">{{input.name}} · {{input.memberCount}}成员 · {{input.issueTime?.slice(0,16).replace('T',' ')}}</option></select></label><label class="forecast-checkbox"><input v-model="latestMain" type="checkbox">使用起报前6小时内同基准主站瞬时湖位</label></div><p v-if="selectedInput" class="muted">气象覆盖 {{selectedInput.start?.replace('T',' ')}}—{{selectedInput.end?.replace('T',' ')}} · {{selectedInput.hours}}小时 · 北京时间</p><details><summary>关注水位</summary><div v-for="(threshold,index) in thresholdRows" :key="index" class="forecast-threshold"><input v-model="threshold.name" placeholder="名称" aria-label="关注水位名称"><input v-model="threshold.level" type="number" step="any" placeholder="水位 / m" aria-label="关注水位高程"><button @click="thresholdRows.splice(index,1);check=null">移除</button></div><button @click="thresholdRows.push({name:'',level:''});check=null">添加关注水位</button></details><div class="actions"><button :disabled="!sourceId||!inputId" @click="preflight">检查起报条件</button><button class="primary" :disabled="!check?.ready||pending.some(t=>t.purpose==='forecast')" @click="predict">开始预测</button></div></fieldset><div v-if="check" class="note" :class="{warning:!check.ready}" role="status"><template v-if="check.ready">起报检查通过 · 末状态 {{check.stateTime?.replace('T',' ')}} · 实际气象推进 {{check.gapHours}} 小时</template><template v-else><b>起报条件未齐备</b><p v-for="(item,index) in check.deficiencies" :key="index">{{item}}</p></template></div></section>
 <section v-if="tab==='results'" class="panel"><div class="panel-title"><h3>预测成果</h3><button :disabled="working" @click="run(load)">刷新</button></div><label class="forecast-result-choice">选择预测<select v-model="selectedForecast" @change="openForecast(selectedForecast)"><option value="">请选择已完成预测</option><option v-for="item in forecasts" :key="item.id" :value="item.id">{{item.name}} · {{item.issueTime?.slice(0,16).replace('T',' ')}} · {{item.memberCount}}成员</option></select></label><p v-if="!forecasts.length" class="empty">尚无已完成预测。</p><template v-if="detail"><div class="forecast-metrics"><div><span>起报湖位</span><b>{{number(detail.initialLakeLevel,3)}} m</b></div><div><span>{{ensembleResult?'最高P50湖位':'最高预测湖位'}}</span><b>{{number(detail.summary?.maximumMedianLevel,3)}} m</b></div><div><span>最大入湖流量</span><b>{{number(detail.summary?.peakInflowM3s,2)}} m³/s</b></div><div><span>成员 / 预见期</span><b>{{detail.memberCount}} / {{number(detail.hours/24,1)}}天</b></div></div><p class="muted">起报 {{detail.issueTime?.replace('T',' ')}} · 结束 {{detail.end?.replace('T',' ')}} · {{detail.lakeCurve?.name}}</p><p v-if="detail.provisional" class="note warning">本预测采用演示或待核实的湖泊库容关系。</p><h4>湖位过程</h4><Chart :rows="resultRows" :series="levelSeries" unit="m" hourly :context="'forecast:'+detail.id+':level'"/><h4>入湖流量</h4><Chart :rows="resultRows" :series="flowSeries" unit="m³/s" hourly :context="'forecast:'+detail.id+':flow'"/><div class="forecast-chart-grid"><div><h4>湖面降水</h4><Chart :rows="resultRows" :series="[{key:'rain',label:'控制成员湖面降水',type:'bar'}]" unit="mm/h" hourly zero :context="'forecast:'+detail.id+':rain'"/></div><div><h4>湖面蒸发</h4><Chart :rows="resultRows" :series="[{key:'evaporation',label:'控制成员湖面蒸发'}]" unit="mm/h" hourly :context="'forecast:'+detail.id+':evap'"/></div></div><p v-if="ensembleResult" class="muted">P10、P50、P90为集合分位数。超限比例表示本次成员预测中的比例。</p><div v-if="detail.exceedance?.length" class="table-wrap"><table><thead><tr><th>关注水位</th><th>水位 / m</th><th>时段内超限成员比例</th></tr></thead><tbody><tr v-for="(item,index) in detail.exceedance" :key="index"><td>{{item.name}}</td><td>{{item.level}}</td><td>{{number(item.anyTimeFraction*100,1)}}%</td></tr></tbody></table></div><details><summary>控制成员逐日过程</summary><div class="table-wrap"><table><thead><tr><th>日期</th><th>湖面降水 mm</th><th>湖面蒸发 mm</th><th>平均入湖流量 m³/s</th><th>日末湖位 m</th><th>小时数</th></tr></thead><tbody><tr v-for="row in dailyResults" :key="row.date"><td>{{row.date}}</td><td>{{number(row.rain,3)}}</td><td>{{number(row.evaporation,3)}}</td><td>{{number(row.flow,3)}}</td><td>{{number(row.level,3)}}</td><td>{{row.count}}</td></tr></tbody></table></div></details></template></section>
 <LakeCurvePanel v-if="tab==='curve'" :boot="boot" :sources="sources" :disabled="working||busy" @saved="curveSaved" @select="curveId=$event" @refresh="emit('refresh')"/>
 <WarningPanel v-if="tab==='warnings'" :forecast-id="selectedForecast||forecasts[0]?.id"/>
 <p v-if="working" class="note" role="status">正在处理，请稍候…</p></div>
